package com.robocontrol.app;
import android.Manifest;import android.app.*;import android.bluetooth.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.view.*;import android.webkit.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.UUID;
public class MainActivity extends Activity{
 static final UUID SPP=UUID.fromString("00001101-0000-1000-8000-00805F9B34FB"); static final int REQ=77;
 int bg=0xff080d18,panel=0xff111a2b,cyan=0xff30dce6; BluetoothAdapter bt;BluetoothSocket sock;OutputStream out;LinearLayout body;TextView status;EditText url;WebView camera;
 public void onCreate(Bundle b){super.onCreate(b);bt=BluetoothAdapter.getDefaultAdapter();shell();drive();}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 GradientDrawable shape(int c,int s){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(15));d.setStroke(dp(1),s);return d;}
 TextView txt(String s,int z,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);if(bold)t.setTypeface(null,1);return t;}
 LinearLayout card(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(14),dp(13),dp(14),dp(13));l.setBackground(shape(panel,0xff304b62));LinearLayout.LayoutParams p=full();p.bottomMargin=dp(12);l.setLayoutParams(p);return l;}
 LinearLayout.LayoutParams full(){return new LinearLayout.LayoutParams(-1,-2);}
 LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 Button btn(String s,Runnable a){Button b=new Button(this);b.setText(s);b.setTextSize(11);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setTypeface(null,1);b.setBackground(shape(0xff1a273b,0xff304b62));b.setOnClickListener(v->a.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(48));p.setMargins(dp(3),dp(4),dp(3),dp(4));b.setLayoutParams(p);return b;}
 void shell(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(17),dp(17),dp(17),dp(10));root.setBackgroundColor(bg);
 LinearLayout h=row();h.addView(txt("ROBO",25,-1,true));h.addView(txt(" CONTROL",25,cyan,true));h.addView(txt("  /  V2.0",10,0xff9aacc0,true));root.addView(h);root.addView(txt("ESP32 COMMAND INTERFACE",10,0xff8499b2,true));
 LinearLayout st=card();status=txt("●  DISCONNECTED",12,0xffffb05c,true);st.addView(status);st.addView(txt("Pair your robot and connect to begin",11,0xffb8c3d1,false));root.addView(st);
 ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));
 LinearLayout nav=row();nav.addView(btn("CONTROL",()->drive()),new LinearLayout.LayoutParams(0,dp(48),1));nav.addView(btn("VISION",()->vision()),new LinearLayout.LayoutParams(0,dp(48),1));nav.addView(btn("SYSTEM",()->system()),new LinearLayout.LayoutParams(0,dp(48),1));root.addView(nav);setContentView(root);}
 void section(String a,String b){TextView t=txt(a,14,cyan,true);t.setPadding(2,dp(12),0,dp(3));body.addView(t);body.addView(txt(b,11,0xffb8c3d1,false));}
 void drive(){body.removeAllViews();section("DRIVE CONTROL","Directional movement • Bluetooth commands");body.addView(btn("CONNECT BLUETOOTH DEVICE",()->choose()),full());
 LinearLayout c=card();c.addView(txt("MOTOR POWER   150 / 255",12,-1,true));SeekBar speed=new SeekBar(this);speed.setMax(255);speed.setProgress(150);speed.setProgressTintList(android.content.res.ColorStateList.valueOf(cyan));speed.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean u){if(u)send("V"+p);}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});c.addView(speed);
 c.addView(txt("MOVEMENT PAD",11,cyan,true));LinearLayout r=row();r.addView(new View(this),new LinearLayout.LayoutParams(0,dp(55),1));r.addView(btn("▲",()->send("F")),new LinearLayout.LayoutParams(0,dp(55),1));r.addView(new View(this),new LinearLayout.LayoutParams(0,dp(55),1));c.addView(r);
 r=row();r.addView(btn("◀",()->send("L")),new LinearLayout.LayoutParams(0,dp(55),1));r.addView(btn("■",()->send("S")),new LinearLayout.LayoutParams(0,dp(55),1));r.addView(btn("▶",()->send("R")),new LinearLayout.LayoutParams(0,dp(55),1));c.addView(r);
 r=row();r.addView(new View(this),new LinearLayout.LayoutParams(0,dp(55),1));r.addView(btn("▼",()->send("B")),new LinearLayout.LayoutParams(0,dp(55),1));r.addView(new View(this),new LinearLayout.LayoutParams(0,dp(55),1));c.addView(r);c.addView(btn("EMERGENCY STOP",()->send("X")));body.addView(c);
 section("SERVO DECK","Hands and head positioning");LinearLayout sv=card();servo(sv,"LEFT HAND","LH_UP","LH_DOWN");servo(sv,"RIGHT HAND","RH_UP","RH_DOWN");servo(sv,"HEAD","HEAD_LEFT","HEAD_RIGHT");sv.addView(btn("CENTER HEAD",()->send("HEAD_CENTER")));body.addView(sv);
 section("AUTONOMOUS MODES","Select a robot mode");String[] modes={"AUTO MODE","OBJECT FOLLOW","OBSTACLE AVOID","VOICE COMMAND","DANCE MODE","RELAX MODE","GAME MODE","CONVERSATION","SALUTE MODE","SAFE MODE"};for(String m:modes)body.addView(btn(m,()->send("MODE:"+m.replace(' ','_'))));}
 void servo(LinearLayout l,String n,String a,String b){LinearLayout r=row();r.addView(txt(n,11,-1,true),new LinearLayout.LayoutParams(0,dp(48),1));r.addView(btn("▲",()->send(a)),new LinearLayout.LayoutParams(0,dp(48),1));r.addView(btn("▼",()->send(b)),new LinearLayout.LayoutParams(0,dp(48),1));l.addView(r);}
 void vision(){body.removeAllViews();section("ROBO VISION","ESP32-CAM live monitoring");LinearLayout c=card();c.addView(txt("CAMERA STREAM ADDRESS",11,cyan,true));url=new EditText(this);url.setSingleLine(true);url.setText("http://192.168.4.1:81/stream");url.setTextColor(-1);url.setHintTextColor(0xffaaaaaa);url.setBackground(shape(panel,cyan));c.addView(url,full());c.addView(btn("CONNECT CAMERA STREAM",()->loadCam()));camera=new WebView(this);camera.setBackgroundColor(Color.BLACK);camera.setWebViewClient(new WebViewClient());c.addView(camera,new LinearLayout.LayoutParams(-1,dp(235)));body.addView(c);body.addView(txt("Use the stream URL configured in your ESP32-CAM firmware. Phone and camera must be on a reachable network. Typical MJPEG endpoint: :81/stream.",12,0xffb8c3d1,false));}
 void loadCam(){String u=url.getText().toString().trim();if(!u.startsWith("http")){toast("Enter a valid camera URL");return;}camera.loadData("<html><body style='margin:0;background:black'><img style='width:100%' src='"+u+"'></body></html>","text/html","UTF-8");}
 void system(){body.removeAllViews();section("SYSTEM STATUS","Bluetooth connection and application information");body.addView(btn("SELECT / CONNECT ROBOT",()->choose()));body.addView(btn("DISCONNECT",()->disconnect()));LinearLayout c=card();c.addView(txt("ROBO CONTROL • PREMIUM EDITION",15,-1,true));c.addView(txt("ESP32 Bluetooth Classic • SPP",12,0xffb8c3d1,false));c.addView(txt("ESP32-CAM network stream viewer",12,0xffb8c3d1,false));c.addView(txt("Drive protocol: F / B / L / R / S / X",12,0xffb8c3d1,false));c.addView(txt("No LED or MPU-6050 controls included.",12,cyan,true));body.addView(c);}
 void choose(){if(bt==null){toast("Bluetooth not supported");return;}if(Build.VERSION.SDK_INT>=31&&checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.BLUETOOTH_CONNECT},REQ);return;}try{if(!bt.isEnabled()){startActivityForResult(new Intent(BluetoothAdapter.ACTION_REQUEST_ENABLE),8);return;}ArrayList<BluetoothDevice> ds=new ArrayList<>(bt.getBondedDevices());if(ds.isEmpty()){toast("Pair ESP32 in Android Bluetooth settings first");startActivity(new Intent(android.provider.Settings.ACTION_BLUETOOTH_SETTINGS));return;}String[] names=new String[ds.size()];for(int i=0;i<ds.size();i++)names[i]=ds.get(i).getName()+" • "+ds.get(i).getAddress();new AlertDialog.Builder(this).setTitle("Choose robot").setItems(names,(d,n)->connect(ds.get(n))).setNegativeButton("Cancel",null).show();}catch(Exception e){toast("Bluetooth permission needed");}}
 void connect(BluetoothDevice d){status.setText("● CONNECTING...");new Thread(()->{try{BluetoothSocket s=d.createRfcommSocketToServiceRecord(SPP);bt.cancelDiscovery();s.connect();OutputStream o=s.getOutputStream();runOnUiThread(()->{sock=s;out=o;status.setText("● CONNECTED • "+d.getName());status.setTextColor(cyan);toast("Robot connected");});}catch(Exception e){runOnUiThread(()->{status.setText("● CONNECTION FAILED");toast("Connection failed; check pairing");});}}).start();}
 void send(String s){try{if(out==null){toast("Connect to robot first");return;}out.write((s+"\n").getBytes());out.flush();}catch(Exception e){toast("Bluetooth send failed");}}
 void disconnect(){try{if(sock!=null)sock.close();}catch(Exception e){}sock=null;out=null;if(status!=null){status.setText("● DISCONNECTED");status.setTextColor(0xffffb05c);}}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==REQ&&g.length>0&&g[0]==0)choose();}
 protected void onDestroy(){disconnect();super.onDestroy();}
}
